const LEVEL_INDEX = new Map(GRAMMAR_LEVELS.map((level, index) => [level.id, index]));

export const GRAMMAR = RAW_GRAMMAR.map((entry, index) => {
  const [
    id,
    level,
    category,
    pattern,
    title,
    summary,
    formation,
    example,
    reading,
    german,
    prompt,
    answer,
    distractors,
    pitfall,
  ] = entry;
  const choices = [answer, ...distractors];
  const rotation = index % choices.length;
  return {
    id,
    level,
    levelIndex: LEVEL_INDEX.get(level),
    frequency: index + 1,
    category,
    pattern,
    title,
    summary,
    formation,
    example,
    reading,
    german,
    prompt,
    answer,
    choices: [...choices.slice(rotation), ...choices.slice(0, rotation)],
    pitfall,
  };
});
